/* Look up a key for a language: requested language first, English as the
   fallback, the key itself as a last resort. {var} placeholders are
   replaced from vars. Pure — used by app.js and the node tests. */
function i18nLookup(lang, key, vars) {
  var entry = I18N[key];
  if (!entry) return key;
  var idx = I18N_LANGS.indexOf(lang);
  var text = (idx >= 0 && entry[idx]) || entry[0] || key;
  if (vars) {
    text = text.replace(/\{(\w+)\}/g, function (m, name) {
      return vars[name] != null ? String(vars[name]) : m;
    });
  }
  return text;
}

if (typeof window !== "undefined") {
  window.I18N = I18N;
  window.I18N_LANGS = I18N_LANGS;
  window.i18nLookup = i18nLookup;
}
if (typeof module !== "undefined" && module.exports) {
  module.exports = { I18N: I18N, I18N_LANGS: I18N_LANGS, i18nLookup: i18nLookup };
}
